import {newState,ingest,identity,infoFor,gate,draftPlan,approve,assign,reviseFacility,taskUpdate,retrieve,restore,brief,taskStates,safeUrl} from './core.mjs';
import {parseCAP} from './cap.mjs';
import {sampleXML,DEMO_NOW} from './fixtures.mjs';
import {assessDraft} from './ai-guard.mjs';
const $=id=>document.getElementById(id);const KEY='floodops.workspace.v1';let state=newState(),exercise=true,worker=null,aiBusy=false;
const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const clock=()=>exercise?DEMO_NOW:new Date().toISOString();
const current=()=>state.alerts.find(a=>identity(a)===state.active);
const time=x=>new Intl.DateTimeFormat('en-IN',{timeZone:'Asia/Kolkata',dateStyle:'medium',timeStyle:'short'}).format(new Date(x))+' IST';
function notice(message,error=false){$('notice').hidden=false;$('notice').className=error?'error':'';$('notice').textContent=message;}
function persist(){try{localStorage.setItem(KEY,JSON.stringify(state));}catch{notice('Browser storage is unavailable. Export your workspace before leaving.',true);}}
function download(name,data,type='application/json'){const url=URL.createObjectURL(new Blob([data],{type})),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function render(){
 const a=current(),p=state.plans[state.active],i=a&&infoFor(a),g=gate(a,clock(),exercise),approved=Boolean(p?.approval&&g.allowed&&p.exercise===exercise);
 $('mode-label').textContent=exercise?'Exercise workspace':'Current-time source review';$('clock-label').textContent=exercise?'Replay clock: '+time(DEMO_NOW):'Review clock: '+time(clock());$('mode').textContent=exercise?'Use current-time review':'Use exercise replay';
 $('count-alerts').textContent=state.alerts.length;$('review-state').textContent=approved?'Reviewed':p?'Review needed':'Not started';$('review-detail').textContent=approved?'By '+p.approval.reviewer:'An explicit human decision';$('count-tasks').textContent=(p?.tasks.filter(t=>t.status==='Done').length||0)+' / '+(p?.tasks.length||0);$('blocked-tasks').textContent=p?p.tasks.filter(t=>t.status==='Blocked').length+' blocked · '+p.tasks.filter(t=>t.owner==='Unassigned').length+' unassigned':'Accountability, in one place';
 $('inbox').innerHTML=state.alerts.length?state.alerts.map(x=>{const f=infoFor(x),key=identity(x);return `<button class="inbox-item ${key===state.active?'active':''}" data-select="${esc(key)}"><span class="tag ${x.cancelledBy||x.supersededBy||x.msgType==='Cancel'?'red':'amber'}">${esc(x.status)} · ${esc(x.msgType)}</span><strong>${esc(f?.headline||x.identifier)}</strong><small>${esc(f?.areaDesc||'Lifecycle record')}</small><small>Issued ${esc(time(x.sent))}</small></button>`;}).join(''):'<p class="empty-small">Start with the sample or import a warning.</p>';
 $('warning-status').textContent=a?(a.cancelledBy?'Cancelled':a.supersededBy?'Superseded':a.status):'No warning selected';
 if(a){$('source').innerHTML=`<div class="alert-heading"><h3>${esc(i?.headline||a.identifier)}</h3><span class="tag amber">${esc(i?.severity||a.msgType)}</span></div><dl class="alert-meta"><div><dt>Affected area</dt><dd>${esc(i?.areaDesc||'See referenced message')}</dd></div><div><dt>Expires</dt><dd>${i?esc(time(i.expires)):'Not applicable'}</dd></div><div><dt>Reported sender · not authenticated</dt><dd>${esc(a.sender)}</dd></div><div><dt>Identifier</dt><dd>${esc(a.identifier)}</dd></div></dl><p class="source-text">${esc(i?.description||'This record references an earlier warning.')}</p>${i?.instruction?`<details><summary>View imported instructions</summary><p class="source-text">${esc(i.instruction)}</p></details>`:''}<div class="source-foot"><span>Content fingerprint ${esc(a.revision.slice(0,14))}…</span>${a.sourceUrl?`<a target="_blank" rel="noopener noreferrer" href="${esc(a.sourceUrl)}">${a.status==='Exercise'?'Exercise format reference':'Open supplied source'} ↗</a>`:'<span>Original URL not provided</span>'}</div><div class="gate-message">${esc(g.reason)}</div>`;}
 $('draft').disabled=!g.allowed;$('generate-ai').disabled=!g.allowed||aiBusy;
 if(p){$('facility').value=p.facility;$('plan').innerHTML=p.tasks.map((t,n)=>`<article class="task"><div class="task-top"><span class="task-index">${String(n+1).padStart(2,'0')}</span><div class="task-content"><h3>${esc(t.title)}</h3><p>${esc(t.text)}</p><a target="_blank" rel="noopener noreferrer" href="${esc(t.source)}">Source note ${esc(t.id)} ↗</a><small>${esc(t.basis)}</small><div class="task-fields"><label>Responsible role<input aria-label="Owner for ${esc(t.id)}" data-owner="${esc(t.id)}" maxlength="100" value="${t.owner==='Unassigned'?'':esc(t.owner)}" placeholder="Assign a role"></label><label>Progress<select aria-label="Status for ${esc(t.id)}" data-status="${esc(t.id)}" ${approved?'':'disabled'}>${taskStates.map(v=>`<option ${t.status===v?'selected':''}>${v}</option>`).join('')}</select></label><button class="secondary" data-save-task="${esc(t.id)}" ${approved?'':'disabled'}>Save progress</button></div><div class="task-note"><input aria-label="Note for ${esc(t.id)}" data-note="${esc(t.id)}" maxlength="2000" value="${esc(t.note)}" placeholder="Optional progress note; avoid personal or medical details" ${approved?'':'disabled'}></div></div></div></article>`).join('')+`<div class="review-box"><h3>${approved?'Plan reviewed':'A person makes the decision'}</h3><p>${approved?'Review is self-reported, saved in this browser and bound to this warning revision.':'Review the original source, local applicability and every draft task. Assign a responsible role to each task. Changing an assignment requires review again.'}</p><label class="check"><input id="source-reviewed" type="checkbox" ${approved?'checked':''}>I reviewed the original source, local plan and this checklist. This is ${exercise?'an exercise':'a preparedness review'}, not authorisation from an emergency authority.</label><div class="review-controls"><input id="reviewer" maxlength="100" aria-label="Reviewer name or role" placeholder="Reviewer name or role" value="${esc(p.approval?.reviewer||'')}"><button id="approve" class="primary" ${g.allowed?'':'disabled'}>${exercise?'Approve exercise plan':'Record plan review'}</button></div></div><div class="brief-actions"><button id="download-brief" class="secondary" ${approved?'':'disabled'}>Download reviewed brief</button></div>`;}
 else $('plan').innerHTML='<p class="empty-small">Your checklist will appear here after source review.</p>';
 $('audit-count').textContent=state.audit.length+' events';$('audit').innerHTML=state.audit.slice(-40).reverse().map(e=>`<div class="audit-event"><time>${esc(time(e.at))}</time><strong>${esc(e.type.replaceAll('_',' '))}</strong><code>${esc(JSON.stringify(e.details))}</code></div>`).join('')||'<p class="empty-small">Actions will be recorded here.</p>';
}
async function run(fn){try{await fn();persist();render();}catch(e){notice(e.message,true);}}
$('load-demo').onclick=()=>run(async()=>{exercise=true;await ingest(state,parseCAP(sampleXML,'https://docs.oasis-open.org/emergency/cap/v1.2/CAP-v1.2.html'),DEMO_NOW);notice('Sample loaded. This is fictional exercise data. Review it, then build a draft checklist.');});
$('mode').onclick=()=>{exercise=!exercise;$('ai-result').hidden=true;render();};
$('open-import').onclick=()=>{$('import-error').textContent='';$('import-dialog').showModal();};$('close-import').onclick=()=>$('import-dialog').close();
$('import-form').onsubmit=async e=>{e.preventDefault();try{const source=$('source-url').value.trim();if(source&&!safeUrl(source))throw new Error('Use an HTTPS source URL without embedded credentials.');const value=parseCAP($('cap-xml').value,source),result=await ingest(state,value,clock());persist();render();$('import-dialog').close();notice(result.duplicate?'This warning was already imported. No duplicate record was created.':'Warning imported. Source authenticity and local relevance still need human review.');}catch(error){$('import-error').textContent=error.message;}};
$('inbox').onclick=e=>{const b=e.target.closest('[data-select]');if(b){state.active=b.dataset.select;$('ai-result').hidden=true;persist();render();}};
$('draft').onclick=()=>run(async()=>{await draftPlan(state,{facility:$('facility').value,exercise,now:clock()});notice('Six source-linked draft tasks created. Assign roles and review before recording progress.');});
$('facility').oninput=()=>{if(state.plans[state.active]){try{reviseFacility(state,$('facility').value,clock());persist();$('review-state').textContent='Review needed';document.querySelectorAll('[data-status],[data-note],[data-save-task],#download-brief').forEach(el=>el.disabled=true);}catch(e){notice(e.message,true);}}};
$('plan').addEventListener('input',e=>{if(e.target.dataset.owner){const p=state.plans[state.active];if(p?.approval){p.approval=null;persist();$('review-state').textContent='Review needed';document.querySelectorAll('[data-status],[data-note],[data-save-task],#download-brief').forEach(el=>el.disabled=true);notice('Assignment edited. Review this plan again before changing task progress.');}}});
$('plan').addEventListener('click',e=>{const task=e.target.closest('[data-save-task]');if(task)run(async()=>{const id=task.dataset.saveTask;await taskUpdate(state,id,{status:document.querySelector(`[data-status="${id}"]`).value,note:document.querySelector(`[data-note="${id}"]`).value},{exercise,now:clock()});notice('Progress saved. No message was sent.');});if(e.target.id==='approve'){const owners=[...document.querySelectorAll('[data-owner]')].map(el=>[el.dataset.owner,el.value]),sourceReviewed=$('source-reviewed').checked,reviewer=$('reviewer').value;run(async()=>{for(const [id,owner] of owners)assign(state,id,owner,clock());await approve(state,{approved:true,sourceReviewed,reviewer,exercise,now:clock()});notice('Assignments and human review recorded for this exact warning and checklist.');});}if(e.target.id==='download-brief'){const p=state.plans[state.active];if(p?.approval&&gate(current(),clock(),exercise).allowed)download('FloodOps-reviewed-brief.txt',brief(current(),p),'text/plain');}});
$('search-form').onsubmit=e=>{e.preventDefault();const hits=retrieve($('search').value);$('search-results').innerHTML=hits.length?hits.map(h=>`<article class="evidence-hit"><h3>${esc(h.id)} · ${esc(h.title)}</h3><p>${esc(h.text)}</p><a href="${esc(h.source)}" target="_blank" rel="noopener noreferrer">Inspect source ↗</a></article>`).join(''):'<p class="empty-small">No supporting note found. This prototype does not invent an answer.</p>';};
$('export').onclick=()=>download('FloodOps-workspace.json',JSON.stringify({...state,exportedAt:new Date().toISOString(),provenance:'Browser-local, mutable prototype record; not an authenticated incident record.'},null,2));
$('restore').onchange=e=>run(async()=>{const file=e.target.files[0];if(!file)return;if(file.size>2000000)throw new Error('Workspace files must be smaller than 2 MB.');state=await restore(JSON.parse(await file.text()));notice('Workspace restored. Approval was reset; review the source and assignments again.');e.target.value='';});
$('generate-ai').onclick=()=>{
 const a=current(),i=infoFor(a);if(aiBusy||!gate(a,clock(),exercise).allowed)return;
 const source=[i.headline,i.description].join('\n');aiBusy=true;$('generate-ai').disabled=true;$('ai-result').hidden=true;$('ai-status').textContent='Preparing local model…';
 if(!worker){worker=new Worker(new URL('./model-worker.mjs',import.meta.url),{type:'module'});worker.onmessage=({data})=>{if(data.type==='progress')$('ai-status').textContent=data.message;else if(data.type==='error'){$('ai-status').textContent=data.message;aiBusy=false;$('generate-ai').disabled=!gate(current(),clock(),exercise).allowed;}else if(data.type==='result'){const check=assessDraft(data.draft,worker.requestSource),same=state.active===worker.requestKey&&exercise===worker.requestExercise;$('ai-status').textContent=same?check.reason+' Model: '+data.model+'. Generation: '+data.elapsedMs+' ms.':'The selected warning or mode changed. This draft was withheld.';if(check.ok&&same){$('ai-result').hidden=false;$('ai-result').textContent='UNREVIEWED LOCAL AI DRAFT\n\n'+data.draft;}state.audit.push({at:clock(),type:'local_ai_experiment',details:{model:data.model,elapsedMs:data.elapsedMs,outputAcceptedByLimitedGuard:check.ok,sourceWarning:worker.requestKey,draft:check.ok?data.draft:null}});persist();aiBusy=false;$('generate-ai').disabled=!gate(current(),clock(),exercise).allowed;}};worker.onerror=()=>{$('ai-status').textContent='Local AI is unavailable in this browser. The preparedness workflow remains available.';aiBusy=false;$('generate-ai').disabled=!gate(current(),clock(),exercise).allowed;};}
 worker.requestSource=source;worker.requestKey=identity(a);worker.requestExercise=exercise;worker.postMessage({source});
};
try{const saved=localStorage.getItem(KEY);if(saved){state=await restore(JSON.parse(saved));notice('Saved workspace reopened. Please renew the human review before changing task progress.');}}catch{notice('Saved data could not be opened. You can restore a previously exported workspace.',true);}
render();setInterval(()=>{if(!exercise)render();},60000);
